import {registerAgentTools} from './agent-tools.js';
import {createVoiceAssistant} from './voice.js';
import {importCSV,importCalendar,exportCalendar} from './integrations.js';
import {DOMAINS,uid,dayKey,plusDays,clock,initialState,makePlan,rankTasks,risks,insights,streak,learningFactor,decompose} from './planner.js';
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
let state,version,user,aiEnabled=false,view='Today',taskFilter='All',query='',authMode='register',planDate=dayKey(),busy=false,timer=null,timerTask=null,timerStarted=0,timerElapsed=0;
const nav=[['Today','sun'],['AI assistant','spark'],['Planner','calendar'],['Tasks','check'],['Goals','target'],['Habits','repeat'],['Wellness','heart'],['Money','wallet'],['Digital balance','phone'],['Insights','chart'],['Integrations','repeat'],['Settings','settings']];
const paths={sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 1.4 1.4m10 10 1.4 1.4M5.6 18.4 1.4-1.4m10-10 1.4-1.4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',calendar:'M7 3v4m10-4v4M4 10h16M5 5h14a1 1 0 0 1 1 1v14H4V6a1 1 0 0 1 1-1',check:'m6 12 4 4 8-8M4 3h16v18H4z',target:'M21 12a9 9 0 1 1-9-9m5 9a5 5 0 1 1-5-5m0 5 9-9m-5 0h5v5',repeat:'m17 2 4 4-4 4M3 11V9a3 3 0 0 1 3-3h15M7 22l-4-4 4-4m14-1v2a3 3 0 0 1-3 3H3',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',wallet:'M20 8V5H5a2 2 0 0 1 0-4h13v4M3 3v17h18V8H3m13 4h5v4h-5z',phone:'M7 2h10v20H7zM10 18h4',chart:'M4 3v18h17M8 16v-5m5 5V7m5 9V4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',plus:'M12 5v14M5 12h14',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',arrow:'M5 12h14m-6-6 6 6-6 6',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',close:'m6 6 12 12M6 18 18 6',logout:'M9 4H4v16h5m5-12 4 4-4 4m-5-4h13',book:'M3 3h7l2 2 2-2h7v17h-7l-2 2-2-2H3zM12 5v17',bolt:'m13 2-9 12h7l-1 8 10-13h-7z',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',edit:'m14 4 6 6M4 20l5-1L21 7l-4-4L5 15z',play:'m8 4 13 8-13 8z'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
const duration=n=>n>=60?`${Math.floor(n/60)}h ${Math.round(n%60)||''}${n%60?'m':''}`:`${Math.round(n)}m`;
const shortDate=d=>new Date(d+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'});
const badge=d=>`<span class="badge ${d.toLowerCase()}">${esc(d)}</span>`;
const button=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const empty=(title,text,action,label)=>`<div class="empty">${icon('spark')}<h3>${title}</h3><p>${text}</p>${action?button(label,action,'primary'):''}</div>`;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>el.classList.remove('show'),4500);}
async function api(action,method='GET',data){const r=await fetch(`/api?action=${action}`,{method,headers:method!=='GET'?{'Content-Type':'application/json'}:{},body:data===undefined?undefined:JSON.stringify(data)});let b;try{b=await r.json();}catch{throw new Error('The server returned an unexpected response. Please try again shortly.');}if(!r.ok){const e=new Error(b.error||'Request failed');e.status=r.status;throw e;}return b;}
async function load(){const session=await api('session');user=session.user;aiEnabled=session.aiEnabled;if(user){const result=await api('state');state=result.state;version=result.version;}render();}
async function save(next,message='Saved'){if(busy)throw new Error('Please wait for the current change to save');busy=true;try{const r=await api('state','PUT',{state:next,version});state=next;version=r.version;render();if(message)toast(message);}catch(e){if(e.status===409)await load();throw e;}finally{busy=false;}}
async function mutate(fn,message){const next=structuredClone(state);fn(next);await save(next,message);}
function openModal(title,content){dialog.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${content}`;dialog.showModal();dialog.querySelector('input,textarea,select,button')?.focus();}
function field(label,name,value='',type='text',attrs=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;}
function select(label,name,options,value){return `<label class="field"><span>${label}</span><select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;}
const textarea=(label,name,value='')=>`<label class="field"><span>${label}</span><textarea name="${name}" maxlength="2000" rows="3">${esc(value)}</textarea></label>`;
const submit=(label='Save')=>`<div class="form-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">${label}</button></div><p class="form-error" role="alert"></p>`;
function auth(){app.innerHTML=`<div class="auth-layout"><section class="auth-story"><a class="brand" href="/"> <span class="brand-mark">o</span> orbit<span class="wordmark-tag">STUDENT LIFE OS</span></a><div><span class="eyebrow">A LITTLE STRUCTURE. MORE POSSIBILITY.</span><h1>Your life.<br>Your goals.<br><em>A plan that fits.</em></h1><p>Make room for what matters—from your next assignment to your evening walk.</p><div class="auth-features"><span>${icon('calendar')} A realistic daily plan</span><span>${icon('repeat')} Adapts when life happens</span><span>${icon('target')} All your goals, together</span></div></div><footer>Built by Rajkamal</footer></section><section class="auth-panel"><div class="auth-card"><span class="eyebrow">WELCOME TO YOUR WORKSPACE</span><h2>${authMode==='register'?'Start with a little clarity.':'Welcome back.'}</h2><p class="muted">${authMode==='register'?'Create your account and build a day that works for you.':'Your next good day starts here.'}</p><form id="auth-form">${authMode==='register'?field('Your name','name','','text','required maxlength="80" autocomplete="name"'):''}${field('Email address','email','','email','required autocomplete="email"')}${field('Password','password','','password',`required minlength="10" maxlength="128" autocomplete="${authMode==='register'?'new-password':'current-password'}"`)}<small>Use at least 10 characters.</small><button class="btn primary wide" type="submit">${authMode==='register'?'Create account':'Sign in'} ${icon('arrow')}</button><p class="form-error" role="alert"></p></form><p class="switch-auth">${authMode==='register'?'Already have an account?':'New to Orbit?'} <button class="text-btn" data-action="switch-auth">${authMode==='register'?'Sign in':'Create account'}</button></p><div class="divider"><span>Want to take a look first?</span></div>${button('Explore a sample workspace','demo','wide')}<p class="small muted">The sample workspace contains fictional data. Your personal account starts empty.</p></div></section></div>`;}
function render(){if(!user){auth();return;}const today=dayKey();const pending=state.tasks.filter(t=>t.status!=='done').length;
 app.innerHTML=`<div class="shell"><aside class="sidebar"><a href="#today" class="brand" data-view="Today"><span class="brand-mark">o</span> orbit</a><span class="sidebar-caption">YOUR STUDENT WORKSPACE</span><nav aria-label="Main navigation">${nav.map(([label,n])=>`<button data-view="${label}" class="nav-item ${view===label?'active':''}" ${view===label?'aria-current="page"':''}>${icon(n)}<span>${label}</span>${label==='Tasks'&&pending?`<b>${pending}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="planner-note">${icon('spark')}<strong>One day at a time.</strong><p>Progress has room for breaks.</p></div><div class="profile-mini"><span class="avatar">${esc(state.profile.name.slice(0,1).toUpperCase())}</span><div><strong>${esc(state.profile.name)}</strong><small>${user.demo?'Sample workspace':'Personal workspace'}</small></div><button class="icon-btn" data-action="logout" aria-label="Sign out">${icon('logout')}</button></div><footer>Built by Rajkamal</footer></div></aside><div class="workspace"><header class="topbar"><span>My workspace <span class="crumb">/ ${view}</span></span><div><span class="date-label">${new Date().toLocaleDateString('en-IN',{weekday:'short',month:'short',day:'numeric'})}</span>${button(icon('spark')+'<span class="voice-label">Voice assistant</span>','voice','voice-launch small-btn')}${button(icon('plus')+' Add task','add-task','primary small-btn')}</div></header>${user.demo?'<div class="demo-banner">You’re exploring sample data. <button data-action="logout" class="text-btn">Sign out to create your own account</button></div>':''}<main id="main" tabindex="-1">${page()}</main><footer class="mobile-credit">Built by Rajkamal</footer></div></div>`;
 document.title=`${view} · Orbit — Built by Rajkamal`;updateTimer();}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${view==='Today'?'YOUR DAY, WITH INTENTION':'YOUR WORKSPACE'}</span><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
function metric(label,value,caption,n){return `<article class="metric"><span class="metric-label">${label}${icon(n)}</span><strong>${value}</strong><span class="small muted">${caption}</span></article>`;}
function page(){switch(view){case'Today':return todayPage();case'AI assistant':return aiPage();case'Planner':return plannerPage();case'Tasks':return tasksPage();case'Goals':return goalsPage();case'Habits':return habitsPage();case'Wellness':return wellnessPage();case'Money':return moneyPage();case'Digital balance':return digitalPage();case'Insights':return insightsPage();case'Settings':return settingsPage();case'Integrations':return integrationsPage();}}
function todayPage(){const today=dayKey(),plan=state.plan?.date===today?state.plan:null,done=state.history.filter(h=>h.date===today&&h.kind==='completed'),focus=done.reduce((n,h)=>n+h.actual,0),w=state.wellness.find(w=>w.date===today),r=risks(state,today).filter(t=>['Overdue','At risk','Due soon'].includes(t.level));const items=insights(state,today);const first=plan?.blocks[0];
 return `${heading(`Let’s make today count, ${esc(state.profile.name.split(' ')[0])}.`,'A clear plan. A little flexibility. Space for you.',button(icon('spark')+' Plan my day','generate-plan','primary'))}<div class="metrics">${metric('Focused time',duration(focus),'Logged today','clock')}${metric('Sessions completed',done.length,`${state.tasks.filter(t=>t.status==='done').length} tasks finished overall`,'check')}${metric('Upcoming deadlines',r.length,'Due soon or needing attention','calendar')}${metric('Daily wellbeing',w?`${w.sleep}h`:'—',w?'Sleep logged last night':'Add your first check-in','heart')}</div><div class="today-grid"><div class="main-column"><section class="focus-card"><div class="section-top"><span class="eyebrow">${first?'UP NEXT':'MAKE YOUR NEXT MOVE'}</span><span class="pill">${icon('spark')} Adaptive planner</span></div><h2>${first?esc(first.title):'Give your day a direction.'}</h2><p>${first?`${duration(first.minutes)} · ${esc(first.domain)} · ${clock(first.start)}–${clock(first.end)}`:'Add your tasks and fixed commitments. Orbit will fit focused work into your available time.'}</p><div class="focus-actions">${first?button(icon('play')+' Start focus','focus','light',`data-id="${first.taskId}"`):button(icon('plus')+' Add your first task','add-task','light')}${button('Open planner '+icon('arrow'),'open-planner','ghost-light')}</div></section><section class="card"><div class="section-top"><h2>Today’s plan <span class="count">${plan?.blocks.length||0}</span></h2>${button('View schedule '+icon('arrow'),'open-planner','text-btn')}</div>${plan?.blocks.length?plan.blocks.slice(0,5).map(blockRow).join(''):empty('Your day is open','Generate a plan to turn your tasks into realistic time blocks.','generate-plan','Plan my day')}${plan?.deferred.length?`<p class="inline-note">${plan.deferred.length} task${plan.deferred.length===1?'':'s'} couldn’t fully fit. Open the planner to review.</p>`:''}</section><section class="card"><div class="section-top"><h2>Daily habits</h2><button class="text-btn" data-view="Habits">View all ${icon('arrow')}</button></div>${habitRows(state.habits.slice(0,3))}</section></div><div class="side-column"><section class="card insight-card"><div class="section-top"><h2>${icon('spark')} A little perspective</h2></div><h3>${esc(items[0].title)}</h3><p>${esc(items[0].text)}</p><button class="text-btn" data-view="Insights">Explore your insights ${icon('arrow')}</button></section><section class="card"><div class="section-top"><h2>On the horizon</h2>${icon('calendar')}</div>${r.length?r.slice(0,4).map(t=>`<div class="deadline-item"><span class="date-square">${new Date(t.due+'T12:00:00').getDate()}<small>${new Date(t.due+'T12:00:00').toLocaleDateString('en',{month:'short'})}</small></span><div><strong>${esc(t.title)}</strong><span class="small ${t.level==='Overdue'?'danger':'muted'}">${esc(t.domain)} · ${t.level}</span></div></div>`).join(''):empty('No urgent deadlines','Add dated tasks to see what’s coming.')}</section><section class="wellbeing-mini"><span>${icon('heart')} CHECK IN WITH YOURSELF</span><h3>How are you feeling today?</h3><p>A better plan starts with understanding your energy.</p>${button('Log wellbeing '+icon('arrow'),'log-wellness','wide')}</section></div></div>${timerPanel()}`;
}
function blockRow(b){return `<div class="plan-row"><div class="time-column">${clock(b.start)}<small>${clock(b.end)}</small></div><span class="domain-line ${b.domain.toLowerCase()}"></span><div class="row-main"><strong>${esc(b.title)}</strong><span class="small muted">${esc(b.domain)} · ${duration(b.minutes)}</span></div><button class="icon-btn" data-action="complete-block" data-id="${b.id}" aria-label="Complete session: ${esc(b.title)}" title="Complete session">${icon('check')}</button><button class="icon-btn" data-action="miss-block" data-id="${b.id}" aria-label="Reschedule session: ${esc(b.title)}" title="Missed session">${icon('repeat')}</button></div>`;}
function plannerPage(){const plan=state.plan?.date===planDate?state.plan:null;return `${heading('A plan that fits your life.','Your fixed commitments stay protected. Large tasks become manageable sessions.',button(icon('repeat')+' Replan remaining day','replan','',`data-date="${planDate}"`))}<div class="planner-controls card"><label class="field"><span>Planning date</span><input type="date" id="plan-date" value="${planDate}"></label><div><strong>${state.profile.availableMinutes/60} hours</strong><span class="small muted">Daily time budget</span></div><div><strong>${state.profile.dailyStart}–${state.profile.dailyEnd}</strong><span class="small muted">Available day window</span></div>${button(icon('spark')+' Generate plan','generate-plan','primary',`data-date="${planDate}"`)}</div><div class="two-columns"><section class="card"><div class="section-top"><h2>${shortDate(planDate)} · Time blocks</h2><span class="badge personal">${duration(plan?.used||0)} planned</span></div>${plan?.blocks.length?plan.blocks.map(blockRow).join(''):empty('No sessions scheduled','Add tasks, check your available hours, then generate a plan.')}${plan?`<p class="inline-note">${state.profile.breakMinutes}-minute breaks between work sessions. Planning budget: ${duration(plan.capacity)}. Fixed commitments are excluded.</p>`:''}${plan?.deferred.length?`<div class="notice warning"><h3>Doesn’t fit yet</h3>${plan.deferred.map(d=>`<p>${esc(d.title)} · ${duration(d.minutes)} remaining</p>`).join('')}<small>These tasks stay in your task list. Adjust time, scope, or deadlines.</small></div>`:''}</section><div><section class="card"><div class="section-top"><h2>Weekly commitments</h2>${button(icon('plus'),'add-commitment','icon-btn','aria-label="Add commitment"')}</div><p class="muted">Classes, travel and other time you want to keep clear.</p>${state.commitments.length?state.commitments.map(c=>`<div class="list-row"><div><strong>${esc(c.title)}</strong><span class="small muted">${c.date?shortDate(c.date):c.days.map(d=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][d]).join(', ')} · ${c.start}–${c.end}</span></div><button class="icon-btn" data-action="edit-commitment" data-id="${c.id}" aria-label="Edit ${esc(c.title)}">${icon('edit')}</button><button class="icon-btn" data-action="delete" data-kind="commitments" data-id="${c.id}" aria-label="Delete ${esc(c.title)}">${icon('trash')}</button></div>`).join(''):empty('Protect your fixed time','Add your classes or regular commitments.','add-commitment','Add commitment')}</section><section class="card"><h2>Why this order?</h2><p>Tasks are ranked by deadline, importance and linked goals. Estimates adapt to your actual session times. Low logged sleep reduces the day’s workload.</p><p class="small muted">Risk flags are estimates, not guarantees. Review the plan before following it.</p></section></div></div>`;}
function taskRow(t){return `<div class="task-row ${t.status==='done'?'completed':''}"><button class="task-checkbox ${t.status==='done'?'checked':''}" data-action="${t.status==='done'?'reopen-task':'complete-task'}" data-id="${t.id}" aria-label="${t.status==='done'?'Reopen':'Complete'} ${esc(t.title)}">${t.status==='done'?icon('check'):''}</button><div class="row-main"><strong>${esc(t.title)}</strong><div class="task-meta">${badge(t.domain)}<span>${icon('clock')} ${duration(t.duration-(t.completedMinutes||0))}</span><span>${icon('calendar')} ${shortDate(t.due)}</span>${t.priority===3?'<span class="danger">High priority</span>':''}</div>${t.notes?`<p class="small muted">${esc(t.notes)}</p>`:''}</div><div class="row-actions">${t.status!=='done'?`<button class="icon-btn" data-action="focus" data-id="${t.id}" aria-label="Focus on ${esc(t.title)}">${icon('play')}</button>`:''}<button class="icon-btn" data-action="edit-task" data-id="${t.id}" aria-label="Edit ${esc(t.title)}">${icon('edit')}</button><button class="icon-btn" data-action="delete" data-kind="tasks" data-id="${t.id}" aria-label="Delete ${esc(t.title)}">${icon('trash')}</button></div></div>`;}
function tasksPage(){let tasks=state.tasks.filter(t=>(taskFilter==='All'||taskFilter==='Completed'&&t.status==='done'||taskFilter===t.domain&&t.status!=='done')&&t.title.toLowerCase().includes(query.toLowerCase()));tasks.sort((a,b)=>(a.status==='done')-(b.status==='done')||a.due.localeCompare(b.due));return `${heading('Everything on your mind.','Capture it here. Let your daily plan handle the order.',button(icon('spark')+' Quick capture','quick-capture',''))}<section class="card capture-bar"><div>${icon('spark')}<strong>Say it naturally</strong><span class="muted">“Finish my Java assignment by Friday, 90 minutes”</span></div>${button('Capture a task '+icon('arrow'),'quick-capture','primary')}</section><div class="task-toolbar"><div class="tabs">${['All',...DOMAINS,'Completed'].map(d=>`<button data-filter="${d}" class="tab ${taskFilter===d?'selected':''}">${d}</button>`).join('')}</div><input id="task-search" type="search" placeholder="Search tasks…" aria-label="Search tasks" value="${esc(query)}"></div><section class="card task-list">${tasks.length?tasks.map(taskRow).join(''):empty(state.tasks.length?'No matching tasks':'A clearer mind starts here',state.tasks.length?'Try a different filter or search.':'Add an assignment, a career task or a personal responsibility.','add-task','Add a task')}</section>${timerPanel()}`;}
function goalsPage(){return `${heading('Big goals. Small steps.','Track meaningful progress across every part of your student life.',button(icon('plus')+' New goal','add-goal','primary'))}<div class="card-grid">${state.goals.length?state.goals.map(g=>`<article class="card goal-card"><div class="section-top">${badge(g.domain)}<div><button class="icon-btn" data-action="edit-goal" data-id="${g.id}" aria-label="Edit ${esc(g.title)}">${icon('edit')}</button><button class="icon-btn" data-action="delete" data-kind="goals" data-id="${g.id}" aria-label="Delete ${esc(g.title)}">${icon('trash')}</button></div></div><h2>${esc(g.title)}</h2><p class="muted">Target date · ${shortDate(g.due)}</p><div class="progress-label"><strong>${g.current} <span class="muted">/ ${g.target} ${esc(g.unit)}</span></strong><span>${Math.round(g.current/g.target*100)}%</span></div><progress max="${g.target}" value="${Math.min(g.current,g.target)}" aria-label="Goal progress"></progress><div class="goal-actions">${button('+ Log progress','goal-progress','',`data-id="${g.id}"`)}${button('Create steps '+icon('arrow'),'goal-steps','text-btn',`data-id="${g.id}"`)}</div></article>`).join(''):empty('What would you like to achieve?','Create an academic, career, wellness or personal goal.','add-goal','Create a goal')}</div>`;}
function habitRows(habits){const today=dayKey(),weekday=new Date().getDay();return habits.length?habits.map(h=>{const checked=h.checks.includes(today),scheduled=h.days.includes(weekday);return `<div class="habit-row"><button class="habit-check ${checked?'checked':''}" data-action="toggle-habit" data-id="${h.id}" aria-label="${checked?'Uncheck':'Check'} ${esc(h.title)}" ${!scheduled?'disabled':''}>${checked?icon('check'):icon('plus')}</button><div class="row-main"><strong>${esc(h.title)}</strong><span class="small muted">${scheduled?'Today’s habit':'Not scheduled today'} · ${h.domain}</span></div><span class="streak">${icon('bolt')} ${streak(h)} day${streak(h)===1?'':'s'}</span></div>`;}).join(''):empty('Make consistency easier','Start with one small habit you can repeat.','add-habit','Add a habit');}
function habitsPage(){return `${heading('Small actions add up.','Build routines that support your goals, one day at a time.',button(icon('plus')+' New habit','add-habit','primary'))}<section class="card">${habitRows(state.habits)}</section>${state.habits.length?`<section class="card"><h2>Your last seven days</h2><div class="table-wrap"><table><thead><tr><th>Habit</th>${Array.from({length:7},(_,i)=>`<th>${shortDate(plusDays(dayKey(),i-6))}</th>`).join('')}<th>Manage</th></tr></thead><tbody>${state.habits.map(h=>`<tr><td>${esc(h.title)}</td>${Array.from({length:7},(_,i)=>{const d=plusDays(dayKey(),i-6),scheduled=h.days.includes(new Date(d+'T12:00:00').getDay());return `<td><button class="history-check ${h.checks.includes(d)?'checked':''}" data-action="toggle-habit" data-id="${h.id}" data-date="${d}" aria-label="Toggle ${esc(h.title)} on ${d}" ${!scheduled?'disabled':''}>${h.checks.includes(d)?'✓':scheduled?'·':'—'}</button></td>`;}).join('')}<td><button class="icon-btn" data-action="edit-habit" data-id="${h.id}" aria-label="Edit ${esc(h.title)}">${icon('edit')}</button><button class="icon-btn" data-action="delete" data-kind="habits" data-id="${h.id}" aria-label="Delete ${esc(h.title)}">${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div></section>`:''}`;}
function wellnessPage(){const w=state.wellness.find(w=>w.date===dayKey());return `${heading('You’re part of the plan, too.','Check in on your sleep, movement, hydration and meals.',button(icon('plus')+' Daily check-in','log-wellness','primary'))}<div class="metrics">${metric('Sleep',w?`${w.sleep}h`:'—',`Your target: ${state.profile.sleepTarget} hours`,'clock')}${metric('Water',w?`${w.water} glasses`:'—',`Your target: ${state.profile.waterTarget} glasses`,'heart')}${metric('Steps',w?w.steps.toLocaleString():'—',`Your target: ${state.profile.stepTarget.toLocaleString()}`,'target')}${metric('Movement',w?`${w.workout}m`:'—','Workout or intentional activity','bolt')}</div><div class="two-columns"><section class="card"><h2>Today’s check-in</h2>${w?`<div class="wellness-summary"><span class="mood-value">${['','Low','Tired','Okay','Good','Great'][w.mood]}</span><span class="muted">How you’re feeling</span></div><h3>Meals & nutrition notes</h3><p>${esc(w.meals)||'No notes yet.'}</p>${button('Update check-in','log-wellness','')}`:empty('How has your day been?','Your check-in helps the planner understand your energy.','log-wellness','Log today')}</section><section class="card"><h2>Recent check-ins</h2>${state.wellness.length?state.wellness.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,14).map(w=>`<div class="list-row"><div><strong>${shortDate(w.date)}</strong><span class="small muted">${w.sleep}h sleep · ${w.water} glasses · ${w.steps.toLocaleString()} steps</span></div><button class="icon-btn" data-action="log-wellness" data-date="${w.date}" aria-label="Edit check-in for ${w.date}">${icon('edit')}</button></div>`).join(''):'<p class="muted">Check-ins will appear here as you log them.</p>'}</section></div>`;}
function moneyPage(){const month=dayKey().slice(0,7),items=state.expenses.filter(e=>e.date.startsWith(month)),sum=type=>items.filter(e=>e.type===type).reduce((n,e)=>n+e.amount,0),spent=sum('expense'),income=sum('income'),saving=sum('saving');return `${heading('A little awareness goes a long way.','Track spending, budget and savings in one place.',button(icon('plus')+' Add transaction','add-expense','primary'))}<div class="metrics">${metric('Spent this month',money(spent),`${month} · Expenses`,'wallet')}${metric('Budget remaining',money(state.profile.monthlyBudget-spent),`Budget: ${money(state.profile.monthlyBudget)}`,'chart')}${metric('Income',money(income),'Recorded this month','plus')}${metric('Savings set aside',money(saving),`Monthly goal: ${money(state.profile.savingsGoal)}`,'target')}</div><div class="two-columns"><section class="card"><div class="section-top"><h2>Transactions</h2><span class="small muted">Latest first</span></div>${state.expenses.length?state.expenses.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<div class="list-row"><div class="row-main"><strong>${esc(e.title)}</strong><span class="small muted">${shortDate(e.date)} · ${esc(e.category)} · ${e.type}</span></div><strong class="${e.type==='income'?'positive':''}">${e.type==='expense'?'−':''}${money(e.amount)}</strong><button class="icon-btn" data-action="edit-expense" data-id="${e.id}" aria-label="Edit ${esc(e.title)}">${icon('edit')}</button><button class="icon-btn" data-action="delete" data-kind="expenses" data-id="${e.id}" aria-label="Delete ${esc(e.title)}">${icon('trash')}</button></div>`).join(''):empty('Know where your money goes','Log your first expense, income or savings transfer.','add-expense','Add transaction')}</section><section class="card"><h2>Where it went this month</h2>${['Food','Travel','Learning','Shopping','Health','Other'].map(c=>{const n=items.filter(e=>e.type==='expense'&&e.category===c).reduce((n,e)=>n+e.amount,0);return `<div class="bar-item"><div><span>${c}</span><strong>${money(n)}</strong></div><progress max="${Math.max(1,spent)}" value="${n}" aria-label="Spending on ${c}"></progress></div>`;}).join('')}<p class="small muted">Savings transfers are tracked separately from expenses. Adjust your budget and savings target in Settings.</p></section></div>`;}
function digitalPage(){const d=state.digital.find(d=>d.date===dayKey());return `${heading('More intention. Less autopilot.','Notice your digital patterns and make space for focused work.',button(icon('plus')+' Log digital activity','log-digital','primary'))}<div class="metrics three">${metric('Screen time',d?duration(d.screen):'—',`Your target: under ${duration(state.profile.screenTarget)}`,'phone')}${metric('Distraction time',d?duration(d.distraction):'—','Part of total screen time','clock')}${metric('Focused work',d?duration(d.focus):'—','Manually logged productive time','target')}</div><div class="two-columns"><section class="card"><h2>Today’s observations</h2><p>${d?esc(d.notes)||'No observations added yet.':'What pulled your attention today? Log what you noticed.'}</p>${button('Update today','log-digital','')}<p class="inline-note">Manual tracking: Orbit does not read your device’s screen-time data. Focus sessions are recorded separately in Insights.</p></section><section class="card"><h2>Activity history</h2>${state.digital.length?state.digital.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,14).map(d=>`<div class="list-row"><div><strong>${shortDate(d.date)}</strong><span class="small muted">${duration(d.screen)} screen · ${duration(d.distraction)} distraction</span></div><button class="icon-btn" data-action="log-digital" data-date="${d.date}" aria-label="Edit digital log for ${d.date}">${icon('edit')}</button></div>`).join(''):'<p class="muted">Your digital activity history will appear here.</p>'}</section></div>`;}
function insightsPage(){const today=dayKey(),recent=state.history.filter(h=>h.date>=plusDays(today,-6)&&h.kind==='completed');return `${heading('See the pattern. Find your rhythm.','Insights from what you actually logged—never invented activity.')}<div class="insight-grid">${insights(state,today).map(i=>`<article class="notice ${i.tone}">${icon('spark')}<h3>${esc(i.title)}</h3><p>${esc(i.text)}</p></article>`).join('')}</div><div class="two-columns"><section class="card"><h2>Focus across your life</h2><p class="muted">Completed session minutes · last 7 days</p>${DOMAINS.map(d=>{const n=recent.filter(h=>h.domain===d).reduce((n,h)=>n+h.actual,0),max=Math.max(60,...DOMAINS.map(x=>recent.filter(h=>h.domain===x).reduce((n,h)=>n+h.actual,0)));return `<div class="bar-item"><div><span>${d}</span><strong>${duration(n)}</strong></div><progress max="${max}" value="${n}" aria-label="${d} focus minutes"></progress></div>`;}).join('')}</section><section class="card"><h2>Estimated vs. actual</h2><p class="muted">Learning from your latest 20 sessions in each area.</p>${DOMAINS.map(d=>`<div class="list-row"><span>${d}</span><strong>${learningFactor(state,d).toFixed(2)}×</strong></div>`).join('')}<p class="small muted">1.00× means no adjustment. Ratios are bounded between 0.60× and 2.50× to limit outliers. No history starts at 1.00×.</p></section></div><section class="card"><h2>Deadline watch</h2><div class="table-wrap"><table><thead><tr><th>Task</th><th>Due date</th><th>Adjusted time</th><th>Outlook</th></tr></thead><tbody>${risks(state,today).map(t=>`<tr><td>${esc(t.title)}</td><td>${shortDate(t.due)}</td><td>${duration(t.adjustedDuration)}</td><td><span class="badge ${t.level==='On track'?'wellness':'finance'}">${t.level}</span></td></tr>`).join('')||'<tr><td colspan="4">Add tasks to see deadline estimates.</td></tr>'}</tbody></table></div><p class="small muted">Risk compares cumulative work due with available time, reserving 20% for breaks and uncertainty. It is a planning heuristic, not a trained prediction model.</p></section><section class="card"><h2>Recent activity</h2>${state.history.slice(-15).reverse().map(h=>`<div class="list-row"><div><strong>${esc(h.title)}</strong><span class="small muted">${shortDate(h.date)} · ${h.kind==='completed'?`${Math.round(h.estimated)}m estimated → ${h.actual}m actual`:`Missed: ${esc(h.reason)}`}</span></div>${badge(h.domain)}</div>`).join('')||'<p class="muted">Your completed and rescheduled sessions appear here.</p>'}</section>`;}
function settingsPage(){const p=state.profile;return `${heading('Make Orbit yours.','Set a realistic time budget, personal targets and your daily rhythm.')}<form id="settings-form"><div class="two-columns"><section class="card"><h2>Profile & daily planning</h2>${field('Your name','name',p.name,'text','required maxlength="80"')}${field('Course / semester','course',p.course,'text','maxlength="150"')}<div class="form-grid">${field('Day starts at','dailyStart',p.dailyStart,'time','required')}${field('Day ends at','dailyEnd',p.dailyEnd,'time','required')}${field('Daily task budget (minutes)','availableMinutes',p.availableMinutes,'number','required min="0" max="1440"')}${field('Break between sessions (minutes)','breakMinutes',p.breakMinutes,'number','required min="0" max="60"')}</div><p class="small muted">Classes are excluded separately in Planner. Sleep outside this window stays protected. Dates use your device’s local time zone.</p></section><section class="card"><h2>Personal targets</h2><div class="form-grid">${field('Sleep target (hours)','sleepTarget',p.sleepTarget,'number','required min="1" max="24" step="0.5"')}${field('Water target (glasses)','waterTarget',p.waterTarget,'number','required min="1" max="30"')}${field('Daily steps target','stepTarget',p.stepTarget,'number','required min="1" max="100000"')}${field('Screen-time target (minutes)','screenTarget',p.screenTarget,'number','required min="1" max="1440"')}${field('Monthly budget (₹)','monthlyBudget',p.monthlyBudget,'number','required min="0" max="100000000"')}${field('Monthly savings goal (₹)','savingsGoal',p.savingsGoal,'number','required min="0" max="100000000"')}</div><button class="btn primary" type="submit">Save settings</button><p class="form-error" role="alert"></p></section></div></form><section class="card"><h2>Your data & privacy</h2><p>Your records are saved to your account on the server. Backups contain your personal records—keep them somewhere private.</p><div class="inline-actions">${button(icon('download')+' Export backup','export','')}${button('Restore backup','import','')}${button('Delete account & data','delete-account','danger-btn')}</div><input id="import-file" type="file" accept="application/json,.json" hidden><div class="notice info"><strong>Assistant: ${aiEnabled?'AI connection available':'Local rules active'}</strong><p>${aiEnabled?'Quick capture can use AI when you explicitly select it. Only the text entered and current date are sent.':'Natural-language capture uses local date and keyword rules. To enable model-assisted interpretation, configure an API key on the server.'} Scheduling always uses the transparent local planning engine.</p></div></section>`;}
function taskForm(id){const t=state.tasks.find(t=>t.id===id)||{title:'',domain:'Academics',duration:45,due:plusDays(dayKey(),1),priority:2,notes:'',goalId:''};openModal(id?'Edit task':'Add a task',`<form id="task-form" data-id="${id||''}">${field('What needs to get done?','title',t.title,'text','required maxlength="200" autofocus')}<div class="form-grid">${select('Life area','domain',DOMAINS,t.domain)}${field('Estimated time (minutes)','duration',t.duration,'number',`required min="${Math.max(5,t.completedMinutes||0)}" max="1440"`)}${field('Due date','due',t.due,'date','required')}${select('Importance','priority',[[1,'Low'],[2,'Normal'],[3,'High']],t.priority)}</div>${select('Linked goal','goalId',[['','No linked goal'],...state.goals.map(g=>[g.id,g.title])],t.goalId)}${textarea('Notes','notes',t.notes)}${id&&t.status!=='done'?button(icon('spark')+' Break into smaller tasks','split-task','',`type="button" data-id="${id}"`):''}${submit(id?'Save changes':'Add task')}</form>`);}
function daysField(selected=[1,2,3,4,5]){return `<fieldset class="days-field"><legend>Repeat on</legend>${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label><input type="checkbox" name="days" value="${i}" ${selected.includes(i)?'checked':''}><span>${d}</span></label>`).join('')}</fieldset>`;}
function entityForm(kind,id){
 if(kind==='goal'){const g=state.goals.find(g=>g.id===id)||{title:'',domain:'Career',target:10,current:0,unit:'sessions',due:plusDays(dayKey(),30)};openModal(id?'Edit goal':'Create a goal',`<form id="goal-form" data-id="${id||''}">${field('Goal','title',g.title,'text','required maxlength="200"')}${select('Life area','domain',DOMAINS,g.domain)}<div class="form-grid">${field('Target amount','target',g.target,'number','required min="1" max="100000000"')}${field('Current progress','current',g.current,'number','required min="0" max="100000000"')}${field('Unit (chapters, sessions…)','unit',g.unit,'text','required maxlength="50"')}${field('Target date','due',g.due,'date','required')}</div>${submit()}</form>`);}
 if(kind==='habit'){const h=state.habits.find(h=>h.id===id)||{title:'',domain:'Personal',days:[0,1,2,3,4,5,6]};openModal(id?'Edit habit':'Create a habit',`<form id="habit-form" data-id="${id||''}">${field('Small action to repeat','title',h.title,'text','required maxlength="200"')}${select('Life area','domain',DOMAINS,h.domain)}${daysField(h.days)}${submit()}</form>`);}
 if(kind==='commitment'){const c=state.commitments.find(c=>c.id===id)||{title:'',days:[1,2,3,4,5],start:'09:30',end:'16:30'};openModal(id?'Edit commitment':'Protect your fixed time',`<form id="commitment-form" data-id="${id||''}">${field('Commitment','title',c.title,'text','required maxlength="200"')}<div class="form-grid">${field('Starts at','start',c.start,'time','required')}${field('Ends at','end',c.end,'time','required')}</div>${c.date?field('Specific date','date',c.date,'date','required'):''}${daysField(c.days)}${submit()}</form>`);}
 if(kind==='expense'){const e=state.expenses.find(e=>e.id===id)||{title:'',amount:0,type:'expense',category:'Food',date:dayKey()};openModal(id?'Edit transaction':'Add transaction',`<form id="expense-form" data-id="${id||''}">${field('Description','title',e.title,'text','required maxlength="200"')}<div class="form-grid">${field('Amount (₹)','amount',e.amount||'','number','required min="0.01" max="100000000" step="0.01"')}${select('Type','type',[['expense','Expense'],['income','Income'],['saving','Savings transfer']],e.type)}${select('Category','category',['Food','Travel','Learning','Shopping','Health','Other'],e.category)}${field('Date','date',e.date,'date','required')}</div>${submit()}</form>`);}
}
function wellbeingForm(date=dayKey()){const w=state.wellness.find(w=>w.date===date)||{date,sleep:8,water:0,steps:0,workout:0,meals:'',mood:3};openModal('Daily wellbeing check-in',`<form id="wellness-form">${field('Date','date',w.date,'date',`required max="${dayKey()}"`)}<div class="form-grid">${field('Sleep last night (hours)','sleep',w.sleep,'number','required min="0" max="24" step="0.5"')}${field('Water (glasses)','water',w.water,'number','required min="0" max="50"')}${field('Steps','steps',w.steps,'number','required min="0" max="200000"')}${field('Workout (minutes)','workout',w.workout,'number','required min="0" max="1440"')}</div>${select('How do you feel?','mood',[[1,'Low'],[2,'Tired'],[3,'Okay'],[4,'Good'],[5,'Great']],w.mood)}${textarea('Meals & nutrition notes','meals',w.meals)}${submit('Save check-in')}</form>`);}
function digitalForm(date=dayKey()){const d=state.digital.find(d=>d.date===date)||{date,screen:0,distraction:0,focus:0,notes:''};openModal('Log digital activity',`<form id="digital-form">${field('Date','date',d.date,'date',`required max="${dayKey()}"`)}${field('Total screen time (minutes)','screen',d.screen,'number','required min="0" max="1440"')}${field('Distraction time within screen time (minutes)','distraction',d.distraction,'number','required min="0" max="1440"')}${field('Productive / focused time (minutes)','focus',d.focus,'number','required min="0" max="1440"')}${textarea('What did you notice?','notes',d.notes)}${submit()}</form>`);}
function completionForm(id,blockId){const t=state.tasks.find(t=>t.id===id);const b=state.plan?.blocks.find(b=>b.id===blockId);if(!t)return;openModal('A little progress. Nicely done.',`<form id="completion-form" data-id="${id}" data-block="${blockId||''}"><p>${esc(t.title)}</p>${field('Actual time spent (minutes)','actual',b?.minutes||Math.max(1,t.duration-t.completedMinutes),'number','required min="1" max="1440"')}${field('Completion date','date',dayKey(),'date',`required max="${dayKey()}"`)}<p class="small muted">${b?'This records the selected session’s share of the task.':'This marks the whole remaining task complete.'} Actual time improves future estimates. Linked goal progress is recorded separately.</p>${submit('Record completion')}</form>`);}
function timerPanel(){if(!timerTask)return '';return `<section class="timer-panel"><span>${icon('clock')} ${esc(timerTask.title)}</span><strong id="timer-display">00:00</strong><div>${button(timer?'Pause':'Resume','timer-toggle','')}${button('Finish session','timer-finish','primary')}</div></section>`;}
function updateTimer(){const el=document.querySelector('#timer-display');if(el){const seconds=Math.floor((timerElapsed+(timer?Date.now()-timerStarted:0))/1000);el.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}}
function stopTimer(){clearInterval(timer);timer=null;timerTask=null;timerElapsed=0;}
let captured=[];
let aiMessages=[],aiSending=false,aiShare=false,aiError='',aiDraft='';
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action],[data-view],[data-filter]');if(!el)return;e.preventDefault();try{
 if(el.dataset.view){view=el.dataset.view;render();document.querySelector('#main')?.focus();return;}
 if(el.dataset.filter){taskFilter=el.dataset.filter;render();return;}
 const action=el.dataset.action,id=el.dataset.id;
 if(action==='close-modal'){voice.stop();dialog.close();return;}
 if(action==='voice'){voice.open();return;}
 if(action==='clear-ai'){aiMessages=[];aiError='';aiDraft='';render();return;}
 if(action==='ai-example'){aiDraft=el.dataset.prompt;render();document.querySelector('#ai-question')?.focus();return;}
 if(action==='calendar-export'){downloadText(exportCalendar(state),'orbit-calendar.ics','text/calendar');return;}
 if(action==='data-import'){integrationImportForm();return;}
 if(action==='sample-csv'){const kind=el.dataset.kind;const templates={wellness:'date,sleep,water,steps,workout,mood,meals\n'+dayKey()+',8,6,7000,30,4,Home cooked meals',digital:'date,screen,distraction,focus,notes\n'+dayKey()+',180,45,120,Focused morning',expenses:'date,title,amount,type,category\n'+dayKey()+',Lunch,100,expense,Food'};downloadText(templates[kind],`orbit-${kind}-template.csv`,'text/csv');return;}
 if(action==='switch-auth'){authMode=authMode==='register'?'login':'register';render();return;}
 if(action==='demo'){el.disabled=true;await api('demo','POST',{today:dayKey()});await load();return;}
 if(action==='logout'){aiMessages=[];aiShare=false;aiError='';aiDraft='';stopTimer();await api('logout','POST',{});user=null;state=null;view='Today';render();return;}
 if(action==='add-task'||action==='edit-task'){taskForm(id);return;}
 if(action==='open-planner'){view='Planner';render();return;}
 if(action==='generate-plan'||action==='replan'){const date=el.dataset.date||dayKey();if(date<dayKey())throw new Error('Choose today or a future date for planning');const now=new Date();const from=action==='replan'&&date===dayKey()?now.getHours()*60+now.getMinutes():0;await mutate(s=>{s.plan=makePlan(s,date,from);},'Plan updated');return;}
 if(action==='complete-block'){const b=state.plan?.blocks.find(b=>b.id===id);if(b)completionForm(b.taskId,id);return;}
 if(action==='complete-task'){completionForm(id);return;}
 if(action==='reopen-task'){await mutate(s=>{const t=s.tasks.find(t=>t.id===id);t.status='pending';t.completedMinutes=0;s.plan=null;},'Task reopened');return;}
 if(action==='miss-block'){const b=state.plan?.blocks.find(b=>b.id===id);if(!b)return;openModal('Life happens. Adjust the plan.',`<form id="miss-form" data-id="${id}"><p>${esc(b.title)}</p>${select('What got in the way?','reason',['Unexpected event','Task took longer','Low energy','Distraction','Other'],'Unexpected event')}${field('Time lost (minutes)','lost',b.minutes,'number','required min="0" max="1440"')}<p class="small muted">The remaining plan moves past this session and your lost time. Lower-priority work may no longer fit.</p>${submit('Rebuild remaining plan')}</form>`);return;}
 for(const kind of ['goal','habit','expense','commitment'])if(action===`add-${kind}`||action===`edit-${kind}`){entityForm(kind,id);return;}
 if(action==='log-wellness'){wellbeingForm(el.dataset.date);return;}
 if(action==='log-digital'){digitalForm(el.dataset.date);return;}
 if(action==='toggle-habit'){const date=el.dataset.date||dayKey();await mutate(s=>{const h=s.habits.find(h=>h.id===id);h.checks=h.checks.includes(date)?h.checks.filter(d=>d!==date):[...h.checks,date];},'Habit updated');return;}
 if(action==='delete'){const kind=el.dataset.kind;openModal('Delete this item?',`<p>This removes the item. Previously recorded activity stays in your history.</p><div class="form-actions">${button('Cancel','close-modal','')}${button('Delete item','confirm-delete','danger-btn',`data-kind="${kind}" data-id="${id}"`)}</div>`);return;}
 if(action==='confirm-delete'){await mutate(s=>{s[el.dataset.kind]=s[el.dataset.kind].filter(x=>x.id!==id);if(el.dataset.kind==='goals')s.tasks.forEach(t=>{if(t.goalId===id)t.goalId='';});s.plan=null;},'Item deleted');dialog.close();return;}
 if(action==='goal-progress'){const g=state.goals.find(g=>g.id===id);openModal('Log goal progress',`<form id="goal-progress-form" data-id="${id}"><p>${esc(g.title)}</p>${field(`Completed ${esc(g.unit)} (total)`,'current',g.current,'number','required min="0" max="100000000"')}${submit()}</form>`);return;}
 if(action==='goal-steps'){const g=state.goals.find(g=>g.id===id);captured=decompose({id:uid(),title:g.title,domain:g.domain,duration:90,completedMinutes:0,due:g.due,priority:2,status:'pending',created:dayKey(),notes:'',goalId:g.id});captureReview('Suggested goal steps · local rules');return;}
 if(action==='split-task'){const t=state.tasks.find(t=>t.id===id);if(t.completedMinutes>0)throw new Error('Split a task before recording progress, or create a new task for the remaining work');const parts=decompose(t);openModal('Break into three steps',`<p>The original task will be replaced by these editable tasks:</p>${parts.map(p=>`<div class="list-row"><strong>${esc(p.title)}</strong><span>${duration(p.duration)}</span></div>`).join('')}<div class="form-actions">${button('Cancel','close-modal','')}${button('Replace with steps','confirm-split','primary',`data-id="${id}"`)}</div>`);captured=parts;return;}
 if(action==='confirm-split'){await mutate(s=>{s.tasks=s.tasks.filter(t=>t.id!==id).concat(captured);s.plan=null;},'Task split into steps');dialog.close();return;}
 if(action==='quick-capture'){openModal('Get it out of your head.',`<form id="capture-form">${textarea('Describe a task or a larger goal','text','')}${select('Create','mode',[['task','One task'],['decompose','A set of smaller steps']],'task')}${aiEnabled?'<label class="check-label"><input type="checkbox" name="useAI"> Use AI to interpret this text (sends this text and date to the AI service)</label>':'<p class="small muted">Local rules recognize dates, weekday names, durations and common life areas.</p>'}${submit('Review suggested tasks')}</form>`);return;}
 if(action==='save-captured'){await mutate(s=>{s.tasks.push(...captured);s.plan=null;},'Tasks added');dialog.close();return;}
 if(action==='focus'){if(timerTask)throw new Error('Finish your current focus session first');timerTask=state.tasks.find(t=>t.id===id);timerStarted=Date.now();timerElapsed=0;timer=setInterval(updateTimer,1000);render();return;}
 if(action==='timer-toggle'){if(timer){timerElapsed+=Date.now()-timerStarted;clearInterval(timer);timer=null;}else{timerStarted=Date.now();timer=setInterval(updateTimer,1000);}render();return;}
 if(action==='timer-finish'){if(timer){timerElapsed+=Date.now()-timerStarted;clearInterval(timer);timer=null;}const t=timerTask;openModal('Save your focus session',`<form id="focus-form" data-id="${t.id}"><p>${esc(t.title)}</p>${field('Actual focused minutes','actual',Math.max(1,Math.round(timerElapsed/60000)),'number','required min="1" max="1440"')}${field('Estimated work completed (minutes)','estimated',Math.min(25,t.duration-t.completedMinutes),'number',`required min="1" max="${t.duration-t.completedMinutes}"`)}<p class="small muted">Record how much of the original estimate you completed. This can leave the task partially done.</p>${submit('Save session')}</form>`);return;}
 if(action==='export'){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`orbit-backup-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(action==='import'){document.querySelector('#import-file').click();return;}
 if(action==='delete-account'){openModal('Delete your account and all records?',`<p>This permanently deletes this account, its tasks, logs and sessions. Export a backup first if you need one.</p><form id="delete-account-form">${field('Type DELETE to confirm','confirmation','','text','required pattern="DELETE"')}${submit('Delete my account')}</form>`);return;}
 }catch(err){toast(err.message);el.disabled=false;}});
function captureReview(source){openModal('Review before adding',`<p class="small muted">${esc(source)}. You can edit each task after adding it.</p>${captured.map(t=>`<div class="list-row"><div><strong>${esc(t.title)}</strong><span class="small muted">${t.domain} · ${duration(t.duration)} · due ${shortDate(t.due)}</span></div></div>`).join('')}<div class="form-actions">${button('Cancel','close-modal','')}${button('Add these tasks','save-captured','primary')}</div>`);}
function numeric(data,keys){keys.forEach(k=>{data[k]=Number(data[k]);});return data;}
function logCompletion(s,t,estimated,actual,date){s.history.push({id:uid(),taskId:t.id,title:t.title,domain:t.domain,kind:'completed',estimated,actual,date,reason:''});t.completedMinutes=Math.min(t.duration,(t.completedMinutes||0)+estimated);if(t.completedMinutes>=t.duration-.01){t.completedMinutes=t.duration;t.status='done';}}
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form)),id=form.dataset.id,submitButton=form.querySelector('[type=submit]');if(submitButton)submitButton.disabled=true;const errorEl=form.querySelector('.form-error');if(errorEl)errorEl.textContent='';try{
 if(form.id==='integration-form'){const file=form.querySelector('[name=file]').files[0];if(!file)throw new Error('Choose a file');if(file.size>1e6)throw new Error('Choose a file under 1 MB');const text=await file.text(),kind=data.kind;let items,skipped=0;if(kind==='calendar'){const imported=importCalendar(text);items=imported.commitments;skipped=imported.skipped;}else items=importCSV(kind,text);if(!items.length)throw new Error('No importable entries found');await mutate(s=>{if(kind==='calendar'){const unique=items.filter(c=>!s.commitments.some(x=>x.title===c.title&&x.date===c.date&&x.start===c.start&&x.end===c.end));s.commitments.push(...unique);s.plan=null;}else if(kind==='expenses'){s.expenses.push(...items.filter(c=>!s.expenses.some(x=>x.title===c.title&&x.date===c.date&&x.amount===c.amount&&x.type===c.type)));}else{for(const item of items){const index=s[kind].findIndex(x=>x.date===item.date);if(index>=0)s[kind][index]=item;else s[kind].push(item);}}},`Imported ${items.length} entries${skipped?`; skipped ${skipped} all-day events`:''}`);dialog.close();return;}
 if(form.id==='auth-form'){await api(authMode,'POST',data);await load();return;}
 if(form.id==='ai-form'){if(aiSending)return;const message=data.message.trim();if(!message)throw new Error('Enter a question');aiDraft=message;aiError='';aiShare=data.sharePlanning==='on';aiSending=true;const accountId=user.id;const history=aiMessages.slice(-12).map(m=>({role:m.role,content:m.content}));render();try{const response=await api('chat','POST',{message,today:dayKey(),history,sharePlanning:aiShare});if(user?.id!==accountId)return;aiMessages.push({role:'user',content:message},{role:'assistant',content:response.answer});aiMessages=aiMessages.slice(-40);aiDraft='';}catch(error){if(user?.id===accountId)aiError=error.message;}finally{aiSending=false;if(user?.id===accountId)render();}return;}
 if(form.id==='settings-form'){numeric(data,['availableMinutes','breakMinutes','monthlyBudget','savingsGoal','sleepTarget','waterTarget','stepTarget','screenTarget']);await mutate(s=>{s.profile=data;s.plan=null;},'Settings updated');return;}
 if(form.id==='capture-form'){if(!data.text?.trim())throw new Error('Describe a task first');const r=await api('assist','POST',{...data,today:dayKey(),useAI:data.useAI==='on'});captured=r.tasks;captureReview(r.source);return;}
 if(form.id==='delete-account-form'){if(data.confirmation!=='DELETE')throw new Error('Type DELETE to confirm');await api('account','DELETE',{});stopTimer();dialog.close();user=null;state=null;render();return;}
 if(form.id==='task-form'){numeric(data,['duration','priority']);data.title=data.title.trim();await mutate(s=>{if(id){Object.assign(s.tasks.find(t=>t.id===id),data);}else{s.tasks.push({...data,id:uid(),created:dayKey(),completedMinutes:0,status:'pending'});}s.plan=null;},'Task saved');}
 if(['goal-form','habit-form','expense-form','commitment-form'].includes(form.id)){const kind=form.id.split('-')[0],collection={goal:'goals',habit:'habits',expense:'expenses',commitment:'commitments'}[kind];if(kind==='goal')numeric(data,['target','current']);if(kind==='expense')numeric(data,['amount']);if(['habit','commitment'].includes(kind)){data.days=new FormData(form).getAll('days').map(Number);if(!data.days.length)throw new Error('Choose at least one day');}await mutate(s=>{if(id)Object.assign(s[collection].find(x=>x.id===id),data);else s[collection].push({...data,id:uid(),...(kind==='habit'?{checks:[]}: {})});s.plan=null;},'Saved');}
 if(form.id==='goal-progress-form'){await mutate(s=>{s.goals.find(g=>g.id===id).current=Number(data.current);},'Progress updated');}
 if(form.id==='wellness-form'||form.id==='digital-form'){const isWell=form.id==='wellness-form';numeric(data,isWell?['sleep','water','steps','workout','mood']:['screen','distraction','focus']);await mutate(s=>{const list=isWell?s.wellness:s.digital,index=list.findIndex(x=>x.date===data.date);if(index>=0)list[index]=data;else list.push(data);if(isWell)s.plan=null;},'Check-in saved');}
 if(form.id==='completion-form'){await mutate(s=>{const t=s.tasks.find(t=>t.id===id),b=s.plan?.blocks.find(b=>b.id===form.dataset.block),estimated=b?b.estimated:t.duration-t.completedMinutes;logCompletion(s,t,estimated,+data.actual,data.date);if(s.plan){s.plan.blocks=s.plan.blocks.filter(block=>block.id!==form.dataset.block&&!(t.status==='done'&&block.taskId===id));s.plan.used=s.plan.blocks.reduce((n,b)=>n+b.minutes,0);if(t.status==='done')s.plan.deferred=s.plan.deferred.filter(x=>x.taskId!==id);}},'Progress recorded');}
 if(form.id==='focus-form'){await mutate(s=>{const t=s.tasks.find(t=>t.id===id);logCompletion(s,t,+data.estimated,+data.actual,dayKey());s.plan=null;},'Focus session saved');stopTimer();render();}
 if(form.id==='miss-form'){await mutate(s=>{const b=s.plan.blocks.find(b=>b.id===id),date=s.plan.date,now=new Date();s.history.push({id:uid(),taskId:b.taskId,title:b.title,domain:b.domain,kind:'missed',estimated:b.estimated,actual:0,date,reason:data.reason});let from=Math.min(1440,b.start+Number(data.lost));if(date===dayKey())from=Math.max(from,now.getHours()*60+now.getMinutes());s.plan=makePlan(s,date,from);},'Remaining day replanned');}
 dialog.close();
 }catch(err){if(errorEl)errorEl.textContent=err.message;else toast(err.message);}finally{if(submitButton)submitButton.disabled=false;}});
document.addEventListener('change',async e=>{if(e.target.id==='ai-share'){aiShare=e.target.checked;aiMessages=[];aiError='';render();}if(e.target.id==='plan-date'){planDate=e.target.value||dayKey();render();}if(e.target.id==='import-file'){try{const file=e.target.files[0];if(!file)return;if(file.size>1e6)throw new Error('Backup must be under 1 MB');const parsed=JSON.parse(await file.text());if(!parsed.state||parsed.state.schema!==1)throw new Error('This is not an Orbit backup');openModal('Replace your data with this backup?',`<p>Your current records will be replaced. Export them first if you need to preserve them.</p><div class="form-actions">${button('Cancel','close-modal','')}<button class="btn primary" id="confirm-import">Restore backup</button></div>`);document.querySelector('#confirm-import').onclick=async()=>{try{await save(parsed.state,'Backup restored');dialog.close();}catch(err){toast(err.message);}};}catch(err){toast(err.message);}}});
document.addEventListener('input',e=>{if(e.target.id==='ai-question')aiDraft=e.target.value;if(e.target.id==='task-search'){const pos=e.target.selectionStart;query=e.target.value;render();const search=document.querySelector('#task-search');search.focus();try{search.setSelectionRange(pos,pos);}catch{}}});

function downloadText(text,filename,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function integrationsPage(){return `${heading('Bring the pieces together.','Import your records and take your plan to your calendar.',button(icon('plus')+' Import a file','data-import','primary'))}<div class="integration-grid"><section class="card"><h2>${icon('calendar')} Calendar</h2><p>Export planned sessions and task deadlines as an ICS calendar file. Import timed events as protected commitments.</p>${button('Export calendar','calendar-export','')}<p class="small muted">Imports accept single-day, non-recurring events in UTC or local floating time. All-day events are skipped. Named time zones and recurrence need conversion first; unsupported files are rejected before saving.</p></section><section class="card"><h2>${icon('heart')} Wearable & wellness records</h2><p>Bring sleep, steps and workouts from an exported file using the CSV template.</p>${button('Download wellness template','sample-csv','', 'data-kind="wellness"')}<p class="small muted">Columns: date, sleep, water, steps, workout, mood, meals. Values are hours, glasses, steps and minutes.</p></section><section class="card"><h2>${icon('wallet')} Finance records</h2><p>Import transactions from a spreadsheet after matching the template columns.</p>${button('Download finance template','sample-csv','', 'data-kind="expenses"')}<p class="small muted">Columns: date, title, amount, type, category. Amounts use INR. Types: expense, income, saving.</p></section><section class="card"><h2>${icon('phone')} Digital activity</h2><p>Import screen-time and distraction records from a CSV export.</p>${button('Download digital template','sample-csv','', 'data-kind="digital"')}<p class="small muted">Columns: date, screen, distraction, focus, notes. Time values use minutes.</p></section></div><section class="notice info"><h3>You stay in control of your records</h3><p>These are file-based integrations. Automatic connections to Google Calendar, wearables, banking and device screen-time services are not configured. Importing wellness or digital activity replaces records for matching dates; duplicate calendar entries and matching finance transactions are skipped.</p></section>`;}
function integrationImportForm(){openModal('Import your records',`<form id="integration-form">${select('Data type','kind',[['calendar','Calendar (.ics)'],['wellness','Wellness (.csv)'],['expenses','Finance (.csv)'],['digital','Digital activity (.csv)']],'calendar')}<label class="field"><span>Choose a file (up to 1 MB)</span><input name="file" type="file" accept=".csv,.ics" required></label><p class="small muted">Use the downloadable templates for CSV files. Matching wellness and digital dates will be replaced. Invalid entries prevent the whole import from saving.</p>${submit('Import records')}</form>`);}
const voice=createVoiceAssistant({openModal,getSummary:()=>{const plan=state.plan;if(!plan||plan.date!==dayKey()||!plan.blocks.length)return 'You do not have a plan for today yet. Add tasks, then say plan my day.';return 'Here is your plan for today. '+plan.blocks.map(b=>`${clock(b.start)}, ${b.title}, for ${b.minutes} minutes.`).join(' ')+(plan.deferred.length?`${plan.deferred.length} tasks could not fully fit.`:'');},onCommand:async command=>{
 if(command.type==='navigate'){dialog.close();view=command.view;render();return;}
 if(command.type==='add'){const r=await api('assist','POST',{text:command.text,today:dayKey(),mode:'task',useAI:false});captured=r.tasks;captureReview('Voice capture · review the interpreted date and duration');return;}
 if(command.type==='plan'||command.type==='replan'){const n=new Date(),from=command.type==='replan'?n.getHours()*60+n.getMinutes():0;await mutate(s=>{s.plan=makePlan(s,dayKey(),from);},'Plan updated by voice');dialog.close();view='Planner';render();return;}
 if(command.type==='complete'||command.type==='focus'){const candidates=state.tasks.filter(t=>t.status!=='done'&&t.title.toLowerCase()===command.text.toLowerCase());if(candidates.length!==1)throw new Error('Say the exact title of one pending task, or open Tasks to select it.');if(command.type==='complete'){completionForm(candidates[0].id);return;}if(timerTask)throw new Error('Finish your current focus session first');timerTask=candidates[0];timerStarted=Date.now();timerElapsed=0;timer=setInterval(updateTimer,1000);dialog.close();view='Today';render();}
}});
dialog.addEventListener('close',()=>voice.stop());

load().catch(err=>{app.innerHTML=`<main class="loading"><h1>Orbit couldn’t connect.</h1><p>${esc(err.message)}</p><button class="btn primary" id="retry">Try again</button></main>`;document.querySelector('#retry').onclick=()=>location.reload();});

const removeAgentTools=registerAgentTools({context:document.modelContext,getPlan:()=>{if(!user)throw new Error('Sign in first');return structuredClone(state.plan);},startTask:title=>{if(!user)throw new Error('Sign in first');taskForm();dialog.querySelector('[name=title]').value=title;}});
window.addEventListener('pagehide',removeAgentTools,{once:true});

function aiPage(){return `${heading('A thinking partner for student life.','Ask questions, break down goals or get suggestions for a realistic day.',button('Clear conversation','clear-ai','',aiSending?'disabled':''))}<div class="two-columns"><section class="card ai-chat"><div class="section-top"><h2>${icon('spark')} Orbit AI</h2><span class="badge ${aiEnabled?'wellness':'finance'}">${aiEnabled?'API key configured':'Setup needed'}</span></div>${!aiEnabled?`<div class="notice warning"><h3>Enable the AI connection</h3><p>In your project folder, copy <code>.env.example</code> to <code>.env</code>, add your OpenAI API key to <code>OPENAI_API_KEY</code>, and restart the server. Keep the key in that file, not in this chat box.</p><p class="small muted">See <code>docs/AI-SETUP.md</code> for Windows instructions. A configured key must have model access and available API usage.</p></div>`:''}<div class="ai-messages" role="log" aria-label="AI conversation" aria-live="polite">${aiMessages.length?aiMessages.map(m=>`<article class="ai-message ${m.role}"><strong>${m.role==='user'?'You':'Orbit AI'}</strong><div>${esc(m.content)}</div></article>`).join(''):'<div class="empty"><h3>What would you like to work on?</h3><p>Try a study question, project idea or a goal you want to break into steps.</p></div>'}${aiSending?'<p class="ai-pending" role="status">Thinking…</p>':''}</div><form id="ai-form"><label class="field"><span>Your question</span><textarea id="ai-question" name="message" maxlength="4000" rows="3" required placeholder="Help me prepare for my Java exam in three days" ${aiSending?'disabled':''}>${esc(aiDraft)}</textarea></label><label class="check-label"><input id="ai-share" type="checkbox" name="sharePlanning" ${aiShare?'checked':''} ${aiSending?'disabled':''}>Share my tasks, goals, commitments and current plan for personalised suggestions</label><p class="small muted">Your question and recent conversation go to OpenAI. Records are shared only if selected above; financial transactions, wellbeing logs and profile identity are excluded. Changing this option clears the conversation.</p><div class="form-actions"><button class="btn primary" type="submit" ${!aiEnabled||aiSending?'disabled':''}>${aiSending?'Thinking…':'Ask Orbit AI'}</button></div><p class="form-error" role="alert">${esc(aiError)}</p></form></section><section class="card"><h2>Start with a question</h2>${['Explain Java inheritance with a simple example','Break learning Spring Boot into a four-week plan','How can I recover after missing a study session?','Review my workload and suggest what I should prioritise'].map(p=>button(esc(p),'ai-example','ai-suggestion',`data-prompt="${esc(p)}" ${aiSending?'disabled':''}`)).join('')}<div class="notice info"><strong>Suggestions you control</strong><p>The AI does not change or complete your tasks. Use Tasks and Planner to apply the suggestions you choose.</p><p>Conversation text stays in this tab’s memory and clears on reload or sign-out. No web browsing is performed.</p></div></section></div>`;}
